SELECT COALESCE(SUM(total_tokens), 0)
FROM dispatch_ai_usage
WHERE tenant_id = #{tenantId}
  AND usage_at >= #{since}
  AND agent_id = #{agentId}

SELECT COUNT(DISTINCT workitem_id)
FROM dispatch_ai_usage
WHERE tenant_id = #{tenantId}
  AND usage_at >= #{since}
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND status = 'SUCCEEDED' AND attempt = 0 AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND attempt > 0 AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM dispatch
WHERE tenant_id = #{tenantId} AND status IN ('FAILED', 'TIMEOUT') AND gmt_create >= #{since} AND is_deleted = 0
  AND agent_id = #{agentId}

SELECT COUNT(*) FROM audit_log
WHERE tenant_id = #{tenantId} AND gmt_create >= #{since}
  AND action IN ('DELETE', 'FORCE_PUBLISH', 'ROLE_CHANGE', 'PERMISSION_GRANT')

SELECT COUNT(*) FROM audit_log
WHERE tenant_id = #{tenantId} AND gmt_create >= #{since}
  AND action IN ('BLOCK', 'REJECT', 'DENY')

SELECT DATE_FORMAT(al.gmt_create, '%Y-%m-%d %H:%i:%s') as timestamp, COALESCE(a.name, CONCAT('user-', al.actor_id)) as worker, al.action as eventType, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(al.detail_json, '$.summary')), CONCAT(al.target_type, '#', al.target_id)) as detail, CASE WHEN al.action IN ('DELETE', 'FORCE_PUBLISH', 'ROLE_CHANGE') THEN 'high' WHEN al.action IN ('UPDATE', 'REJECT', 'RETRY') THEN 'medium' ELSE 'low' END as riskLevel FROM audit_log al LEFT JOIN agent a ON al.actor_id = a.id AND al.tenant_id = a.tenant_id WHERE al.tenant_id = #{tenantId} AND al.gmt_create >= DATE_SUB(NOW(), INTERVAL
7 90 30
DAY)
AND CASE WHEN al.action IN ('DELETE', 'FORCE_PUBLISH', 'ROLE_CHANGE') THEN 'high' WHEN al.action IN ('UPDATE', 'REJECT', 'RETRY') THEN 'medium' ELSE 'low' END = #{riskLevel}
AND a.id = #{workerId}
ORDER BY al.gmt_create DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM audit_log al LEFT JOIN agent a ON al.actor_id = a.id AND al.tenant_id = a.tenant_id WHERE al.tenant_id = #{tenantId} AND al.gmt_create >= DATE_SUB(NOW(), INTERVAL
7 90 30
DAY)
AND CASE WHEN al.action IN ('DELETE', 'FORCE_PUBLISH', 'ROLE_CHANGE') THEN 'high' WHEN al.action IN ('UPDATE', 'REJECT', 'RETRY') THEN 'medium' ELSE 'low' END = #{riskLevel}
AND a.id = #{workerId}
